/*
 * SPEED PASS + CAUSAL PILL ACTIVATION (SH1-SH4).
 *
 * Same artwork, layout, copy, pill geometry, icons, typography and approved
 * active colours. What changed is pacing and one piece of meaning:
 *
 *  - The cycle no longer opens by tearing the finished composition down. It
 *    starts UNCONNECTED and builds forward once, then parks on the complete
 *    composition. 12,000ms -> 1,700ms, with no dead tail.
 *  - Each pill starts GRAY and takes its approved colour only when the connector
 *    reaches its left edge, wiping left to right. Colour is a consequence of the
 *    connection arriving, never a timer or a decorative cycle.
 *
 * Beat times are authored in MILLISECONDS below; keyframe offsets are derived
 * from CYCLE_DURATION_MS so a beat is moved by editing its own two numbers.
 */
const CYCLE_DURATION_MS = 1700;

/** Semantic beats, ms from the cycle start. Order is the approved story. */
const BEATS = {
  shareBranch: [0, 140],
  sharePill: [110, 280],
  shareArrow: [220, 420],
  sharePanel: [300, 800],
  /*
   * The shadow rises with the panel and decays as it lands, one continuous
   * apex rather than a pulse. It starts on the same frame the panel starts
   * moving, so it can neither arrive early nor lag behind.
   */
  /*
   * Convergence tail. The feathered sweep cannot reach full white on its own -
   * its gradient is still ramping across the left of the mask region when it
   * lands - so a solid pass brings the last of the panel up. That pass used to
   * be a 40ms linear 0 -> 1, which is the step that made the reveal appear to
   * snap to 100% after progressing smoothly. It now rises over the final 240ms
   * of the same reveal window, on the state curve, so the last stretch is a
   * continuation of the same movement rather than a handoff.
   */
  shareSolid: [560, 800],
  shareShadowIn: [300, 620],
  shareShadowOut: [620, 880],
  deployBranch: [400, 560],
  deployPill: [530, 700],
  deployArrow: [640, 860],
  deployPanel: [720, 1320],
  deploySolid: [1080, 1320],
  deployShadowIn: [720, 1060],
  deployShadowOut: [1060, 1400],
} as const;

/** ms -> keyframe offset. Every percentage in the sheet comes from here. */
const at = (ms: number) => ((ms / CYCLE_DURATION_MS) * 100).toFixed(4) + "%";

/*
 * HOVER TRANSACTION.
 *
 *   settled -> eased reverse -> exact frame 0 -> short hold -> forward -> settled
 *
 * Both directions are SCRUBBED by the controller on one master progress: each
 * frame maps progress to a single authored time that is written to all twelve
 * tracks, so the composition can only move as one and no track can drift.
 *
 * The reverse is EASED (balanced ease-in-out): it catches motion gently, covers
 * ground quickly, and settles into frame 0 with velocity near zero, so there is
 * no snap at the boundary. The forward half deliberately uses LINEAR master
 * progress - the approved choreography already carries its own per-beat easing,
 * and anything other than linear here would move those beats off their approved
 * wall-clock times.
 */
const HOVER_REVERSE_MS = 1000;
const HOVER_HOLD_MS = 100;

/** Solver for a CSS-style cubic-bezier, for the scrubbed reverse progress. */
function cubicBezier(p1x: number, p1y: number, p2x: number, p2y: number) {
  const cx = 3 * p1x;
  const bx = 3 * (p2x - p1x) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * p1y;
  const by = 3 * (p2y - p1y) - cy;
  const ay = 1 - cy - by;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;
  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 8; i += 1) {
      const error = sampleX(t) - x;
      if (Math.abs(error) < 1e-6) return sampleY(t);
      const slope = slopeX(t);
      if (Math.abs(slope) < 1e-6) break;
      t -= error / slope;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 24; i += 1) {
      const value = sampleX(t);
      if (Math.abs(value - x) < 1e-6) break;
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return sampleY(t);
  };
}

/** Balanced ease-in-out for the rewind. Not front-loaded: no jump on entry. */
const easeHoverReverse = cubicBezier(0.42, 0, 0.58, 1);
/** The forward half keeps the approved beat clock exactly. */
const linearProgress = (x: number) => x;

/*
 * Positional entrance for each result panel: it begins slightly to the RIGHT of
 * its approved position and travels LEFT into place while it reveals, so the
 * reveal reads as an arrival rather than something switching on in place. Small
 * on purpose - a slide would compete with the connector, which is the focal
 * movement. The end value is exactly 0, so the settled geometry is the approved
 * one to the pixel.
 */
const PANEL_ENTRANCE_PX = 16;

/** Movement and reveals. */
const EASE_MOVE = "cubic-bezier(.33, 1, .68, 1)";
/** Opacity and colour-state transitions. */
const EASE_STATE = "cubic-bezier(.4, 0, .2, 1)";
/*
 * The pill colour wipe. Deliberately NOT an ease-out: an ease-out spends its
 * last 40% crawling, which would make the colour appear to stall just before the
 * right edge. A gentle ease-in-out keeps the leading edge moving cleanly all the
 * way across and still starts and ends without a jerk.
 */
const EASE_WIPE = "cubic-bezier(.4, 0, .3, 1)";

/**
 * Extract a balanced <g>...</g> starting at `openTag`.
 *
 * Needed because the causal pill activation renders the pill TWICE - once in its
 * approved colours and once desaturated on top - and the duplicate has to be the
 * whole group, not just its opening tag. Verified safe to duplicate: neither pill
 * group contains an `id` attribute, so no reference can be broken by the copy.
 */
function extractGroup(source: string, openTag: string) {
  const start = source.indexOf(openTag);
  if (start < 0) return null;
  let depth = 0;
  let i = start;
  while (i < source.length) {
    if (source.startsWith("<g", i) && /[\s>]/.test(source[i + 2] ?? "")) {
      depth += 1;
      i += 2;
      continue;
    }
    if (source.startsWith("</g>", i)) {
      depth -= 1;
      if (depth === 0) return { start, end: i + 4, text: source.slice(start, i + 4) };
      i += 4;
      continue;
    }
    i += 1;
  }
  return null;
}

/*
 * The INACTIVE pill palette.
 *
 * Every value here is a neutral already used elsewhere in this same SVG -
 * #F5F5F5 for the surface, #C4C4C4 for the border, #8F8F8F for icon and label -
 * so the disconnected pill sits inside the existing visual system rather than
 * introducing a new tone.
 *
 * This replaces a `filter: grayscale(1)` on the duplicate, which was the cause
 * of the pills reading BLACK rather than grey: grayscale preserves luminance,
 * and the Deploy label is #181839, a near-black navy that desaturates to roughly
 * #1A1A1A. Recolouring by role keeps the label legibly grey instead.
 */
const PILL_INACTIVE_SURFACE = "#F5F5F5";
const PILL_INACTIVE_BORDER = "#C4C4C4";
const PILL_INACTIVE_INK = "#8F8F8F";

/** Active colour -> inactive neutral, per pill, by role. */
const PILL_GREY_MAP: Record<string, Record<string, string>> = {
  share: {
    "#F4F9FF": PILL_INACTIVE_SURFACE,
    "#0D76F2": PILL_INACTIVE_BORDER,
    "#10519E": PILL_INACTIVE_INK,
    "#153B66": PILL_INACTIVE_INK,
  },
  deploy: {
    "#F9F9FF": PILL_INACTIVE_SURFACE,
    "#5757C7": PILL_INACTIVE_BORDER,
    "#181839": PILL_INACTIVE_INK,
  },
};

/**
 * Replace a pill group with an active layer and a grey layer stacked over it.
 *
 * The ACTIVE layer is the original group, untouched and unmasked, so the settled
 * state is pixel-identical to the approved design and its shadow is never
 * clipped. The GREY layer is the same markup with its colours swapped for the
 * neutrals above, sitting on top, and it is what animates: clipping it away from
 * the left uncovers the approved colour underneath, left to right. Nothing is
 * crossfaded, no opacity is dimmed, and no new tone is invented.
 *
 * The white-to-transparent sheen gradient is left alone deliberately - it is
 * colourless, so it keeps the inactive pill made of the same material.
 */
function splitPill(source: string, filterId: string, name: string) {
  const group = extractGroup(source, '<g filter="url(#' + filterId + ')">');
  if (!group) return source;

  let grey = group.text;
  for (const [active, neutral] of Object.entries(PILL_GREY_MAP[name] ?? {})) {
    grey = grey.split('"' + active + '"').join('"' + neutral + '"');
  }

  const layered =
    '<g class="sv-' + name + '-pill-active">' + group.text + "</g>" +
    '<g class="sv-' + name + '-pill-grey">' + grey + "</g>";
  return source.slice(0, group.start) + layered + source.slice(group.end);
}

function createAnimatedMarkup(source: string) {
  const styles = `
    <style>
      /*
       * Base = the SETTLED composition, which is exactly what the SVG is
       * authored as. Every animation therefore ENDS on its base value, so when
       * the controller removes the running class the visual parks with no jump,
       * and reduced motion (animations off) shows the finished, meaningful
       * state. The one non-obvious member is the grey pill layer: its resting
       * state is fully clipped away, because "settled" means the approved colour
       * is showing.
       */
      .share-svg .sv-share-pill-grey,
      .share-svg .sv-deploy-pill-grey {
        clip-path: inset(0 0 0 100%);
      }

      .share-svg .sv-share-branch,
      .share-svg .sv-share-arrow,
      .share-svg .sv-deploy-branch,
      .share-svg .sv-deploy-arrow,
      .share-svg .sv-share-shadow,
      .share-svg .sv-deploy-shadow,
      .share-svg .sv-share-mask-sweep,
      .share-svg .sv-deploy-mask-sweep,
      .share-svg .sv-share-mask-solid,
      .share-svg .sv-deploy-mask-solid {
        transform-box: fill-box;
        transform-origin: center;
        will-change: opacity, transform, clip-path;
      }
      .share-svg .sv-share-entrance,
      .share-svg .sv-deploy-entrance { will-change: transform; }
      .share-svg .sv-share-pill-grey,
      .share-svg .sv-deploy-pill-grey { will-change: clip-path; }

      .share-svg.share-motion-active .sv-share-branch {
        animation: sv-share-branch-cycle ${CYCLE_DURATION_MS}ms ${EASE_MOVE} 1 both;
      }
      .share-svg.share-motion-active .sv-share-arrow {
        animation: sv-share-arrow-cycle ${CYCLE_DURATION_MS}ms ${EASE_MOVE} 1 both;
      }
      .share-svg.share-motion-active .sv-deploy-branch {
        animation: sv-deploy-branch-cycle ${CYCLE_DURATION_MS}ms ${EASE_MOVE} 1 both;
      }
      .share-svg.share-motion-active .sv-deploy-arrow {
        animation: sv-deploy-arrow-cycle ${CYCLE_DURATION_MS}ms ${EASE_MOVE} 1 both;
      }
      /*
       * CAUSAL PILL ACTIVATION. The grey layer is clipped away from its LEFT
       * edge, so the approved colour underneath is uncovered left to right,
       * starting at the exact moment the connector reaches the pill.
       */
      .share-svg.share-motion-active .sv-share-pill-grey {
        animation: sv-share-pill-activate ${CYCLE_DURATION_MS}ms ${EASE_WIPE} 1 both;
      }
      .share-svg.share-motion-active .sv-deploy-pill-grey {
        animation: sv-deploy-pill-activate ${CYCLE_DURATION_MS}ms ${EASE_WIPE} 1 both;
      }
      .share-svg.share-motion-active .sv-share-shadow {
        animation: sv-share-shadow-cycle ${CYCLE_DURATION_MS}ms ${EASE_STATE} 1 both;
      }
      .share-svg.share-motion-active .sv-deploy-shadow {
        animation: sv-deploy-shadow-cycle ${CYCLE_DURATION_MS}ms ${EASE_STATE} 1 both;
      }
      .share-svg.share-motion-active .sv-share-mask-sweep {
        animation: sv-share-panel-cycle ${CYCLE_DURATION_MS}ms ${EASE_MOVE} 1 both;
      }
      .share-svg.share-motion-active .sv-deploy-mask-sweep {
        animation: sv-deploy-panel-cycle ${CYCLE_DURATION_MS}ms ${EASE_MOVE} 1 both;
      }
      /*
       * Positional entrance. Runs over exactly the panel reveal window, so the
       * travel and the wipe are one action rather than two.
       */
      .share-svg.share-motion-active .sv-share-entrance {
        animation: sv-share-entrance-cycle ${CYCLE_DURATION_MS}ms ${EASE_MOVE} 1 both;
      }
      .share-svg.share-motion-active .sv-deploy-entrance {
        animation: sv-deploy-entrance-cycle ${CYCLE_DURATION_MS}ms ${EASE_MOVE} 1 both;
      }
      /*
       * The convergence pass shares the state curve with the shadow, so the two
       * things that finish the entrance finish on the same shape. It starts
       * slowly, which is what keeps the left of the panel from brightening ahead
       * of the sweep, and eases into full rather than arriving at it.
       */
      .share-svg.share-motion-active .sv-share-mask-solid {
        animation: sv-share-solid-mask-cycle ${CYCLE_DURATION_MS}ms ${EASE_STATE} 1 both;
      }
      .share-svg.share-motion-active .sv-deploy-mask-solid {
        animation: sv-deploy-solid-mask-cycle ${CYCLE_DURATION_MS}ms ${EASE_STATE} 1 both;
      }

      /* Connectors draw downward from the folder, then hold. */
      @keyframes sv-share-branch-cycle {
        0% { opacity: 0; clip-path: inset(100% 0 0 0); }
        ${at(BEATS.shareBranch[1])}, 100% { opacity: 1; clip-path: inset(0); }
      }
      @keyframes sv-deploy-branch-cycle {
        0%, ${at(BEATS.deployBranch[0])} { opacity: 0; clip-path: inset(0 0 100% 0); }
        ${at(BEATS.deployBranch[1])}, 100% { opacity: 1; clip-path: inset(0); }
      }
      /* Arrows continue the same left-to-right travel into the result panel. */
      @keyframes sv-share-arrow-cycle {
        0%, ${at(BEATS.shareArrow[0])} { opacity: 0; clip-path: inset(0 100% 0 0); }
        ${at(BEATS.shareArrow[1])}, 100% { opacity: 1; clip-path: inset(0); }
      }
      @keyframes sv-deploy-arrow-cycle {
        0%, ${at(BEATS.deployArrow[0])} { opacity: 0; clip-path: inset(0 100% 0 0); }
        ${at(BEATS.deployArrow[1])}, 100% { opacity: 1; clip-path: inset(0); }
      }
      /*
       * Grey clipped away from the left: inset(0 0 0 0) is fully grey, and the
       * left inset growing to 100% uncovers the approved colour left to right.
       * The wipe starts only when the connector has arrived.
       */
      @keyframes sv-share-pill-activate {
        0%, ${at(BEATS.sharePill[0])} { clip-path: inset(0 0 0 0); }
        ${at(BEATS.sharePill[1])}, 100% { clip-path: inset(0 0 0 100%); }
      }
      @keyframes sv-deploy-pill-activate {
        0%, ${at(BEATS.deployPill[0])} { clip-path: inset(0 0 0 0); }
        ${at(BEATS.deployPill[1])}, 100% { clip-path: inset(0 0 0 100%); }
      }
      /* Result panels: feathered sweep in, then the solid mask locks them. */
      @keyframes sv-share-panel-cycle {
        0%, ${at(BEATS.sharePanel[0])} { transform: translateX(280px); }
        ${at(BEATS.sharePanel[1])}, 100% { transform: translateX(0); }
      }
      @keyframes sv-deploy-panel-cycle {
        0%, ${at(BEATS.deployPanel[0])} { transform: translateX(280px); }
        ${at(BEATS.deployPanel[1])}, 100% { transform: translateX(0); }
      }
      @keyframes sv-share-entrance-cycle {
        0%, ${at(BEATS.sharePanel[0])} { transform: translateX(${PANEL_ENTRANCE_PX}px); }
        ${at(BEATS.sharePanel[1])}, 100% { transform: translateX(0); }
      }
      @keyframes sv-deploy-entrance-cycle {
        0%, ${at(BEATS.deployPanel[0])} { transform: translateX(${PANEL_ENTRANCE_PX}px); }
        ${at(BEATS.deployPanel[1])}, 100% { transform: translateX(0); }
      }
      @keyframes sv-share-solid-mask-cycle {
        0%, ${at(BEATS.shareSolid[0])} { opacity: 0; }
        ${at(BEATS.shareSolid[1])}, 100% { opacity: 1; }
      }
      @keyframes sv-deploy-solid-mask-cycle {
        0%, ${at(BEATS.deploySolid[0])} { opacity: 0; }
        ${at(BEATS.deploySolid[1])}, 100% { opacity: 1; }
      }
      /* Soft lift under each panel as it lands, then away again. */
      @keyframes sv-share-shadow-cycle {
        0%, ${at(BEATS.shareShadowIn[0])} { opacity: 0; }
        ${at(BEATS.shareShadowIn[1])}, ${at(BEATS.shareShadowOut[0])} { opacity: .085; }
        ${at(BEATS.shareShadowOut[1])}, 100% { opacity: 0; }
      }
      @keyframes sv-deploy-shadow-cycle {
        0%, ${at(BEATS.deployShadowIn[0])} { opacity: 0; }
        ${at(BEATS.deployShadowIn[1])}, ${at(BEATS.deployShadowOut[0])} { opacity: .085; }
        ${at(BEATS.deployShadowOut[1])}, 100% { opacity: 0; }
      }

      @media (prefers-reduced-motion: reduce) {
        .share-svg.share-motion-active * { animation: none !important; }
      }
    </style>
  `;

  const maskDefs = `
    <linearGradient id="sv-reveal-feather" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="black"/>
      <stop offset="0.18" stop-color="white" stop-opacity="0.18"/>
      <stop offset="0.38" stop-color="white" stop-opacity="0.72"/>
      <stop offset="0.58" stop-color="white"/>
      <stop offset="1" stop-color="white"/>
    </linearGradient>
    <filter id="sv-soft-reveal-shadow" x="-30%" y="-35%" width="165%" height="180%">
      <feGaussianBlur stdDeviation="12"/>
    </filter>
    <mask id="sv-share-panel-mask" maskUnits="userSpaceOnUse" x="530" y="105" width="440" height="180">
      <rect class="sv-share-mask-sweep" x="530" y="105" width="440" height="180" fill="url(#sv-reveal-feather)"/>
      <rect class="sv-share-mask-solid" x="530" y="105" width="440" height="180" fill="white"/>
    </mask>
    <mask id="sv-deploy-panel-mask" maskUnits="userSpaceOnUse" x="530" y="322" width="440" height="330">
      <rect class="sv-deploy-mask-sweep" x="530" y="322" width="440" height="330" fill="url(#sv-reveal-feather)"/>
      <rect class="sv-deploy-mask-solid" x="530" y="322" width="440" height="330" fill="white"/>
    </mask>
  `;

  const shareShadow = `
    <rect class="sv-share-shadow" x="548" y="126" width="390" height="132" rx="18"
      fill="#525866" opacity="0" filter="url(#sv-soft-reveal-shadow)" pointer-events="none"/>
  `;
  const deployShadow = `
    <rect class="sv-deploy-shadow" x="548" y="350" width="390" height="272" rx="18"
      fill="#525866" opacity="0" filter="url(#sv-soft-reveal-shadow)" pointer-events="none"/>
  `;

  const withPills = splitPill(
    splitPill(source, "filter11_di_964_1383406", "share"),
    "filter3_di_964_1383406",
    "deploy",
  );
  const withPanels = wrapPanel(
    wrapPanel(withPills, "filter4_ddddii_964_1383406", "share", shareShadow),
    "filter7_ddddii_964_1383406",
    "deploy",
    deployShadow,
  );

  return withPanels
    .replace("<svg ", '<svg class="share-svg" ')
    .replace(
      '<path d="M260.667 333C260.667 334.841',
      '<path class="sv-share-branch" d="M260.667 333C260.667 334.841',
    )
    .replace(
      '<path d="M490 190.375C489.655',
      '<path class="sv-share-arrow" d="M490 190.375C489.655',
    )
    .replace(
      '<path d="M490 464.375C489.655',
      '<path class="sv-deploy-arrow" d="M490 464.375C489.655',
    )
    .replace(
      '<path d="M260.667 333C260.667 331.159',
      '<path class="sv-deploy-branch" d="M260.667 333C260.667 331.159',
    )
    .replace("<defs>", `${styles}<defs>${maskDefs}`);
}

/**
 * Wrap a result panel and its shadow in one entrance group.
 *
 * The wrapper is what translates, and the masked panel sits INSIDE it, so the
 * reveal window travels with the panel rather than the panel sliding underneath
 * a stationary mask - crop, masks and final geometry are all preserved. The
 * shadow rides in the same wrapper, which is what makes the movement, the reveal
 * and the shadow read as a single entrance instead of three effects.
 */
function wrapPanel(
  source: string,
  filterId: string,
  name: string,
  shadowRect: string,
) {
  const openTag = '<g filter="url(#' + filterId + ')">';
  const group = extractGroup(source, openTag);
  if (!group) return source;

  const masked = group.text.replace(
    openTag,
    '<g class="sv-' + name + '-panel" mask="url(#sv-' + name +
      '-panel-mask)" filter="url(#' + filterId + ')">',
  );
  const wrapped =
    '<g class="sv-' + name + '-entrance">' + shadowRect + masked + "</g>";
  return source.slice(0, group.start) + wrapped + source.slice(group.end);
}

const animatedSvgMarkup = createAnimatedMarkup(svgMarkup);

export function ShareVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const stopTimerRef = useRef<number | null>(null);
  const isHoverReplayReadyRef = useRef(false);
  /** One hover transaction at a time, so re-entry cannot stack controllers. */
  const hoverRunningRef = useRef(false);
  /** rAF handle of the master clock that drives both hover directions. */
  const scrubFrameRef = useRef<number | null>(null);

  const clearStopTimer = () => {
    if (stopTimerRef.current !== null) {
      window.clearTimeout(stopTimerRef.current);
      stopTimerRef.current = null;
    }
    if (scrubFrameRef.current !== null) {
      cancelAnimationFrame(scrubFrameRef.current);
      scrubFrameRef.current = null;
    }
  };

  const getSvg = () => containerRef.current?.querySelector<SVGSVGElement>("svg") ?? null;

  const handlePointerEnter = (event: PointerEvent<HTMLDivElement>) => {
    if (
      !isHoverReplayReadyRef.current ||
      hoverRunningRef.current ||
      event.pointerType === "touch" ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
    ) {
      return;
    }

    const svg = getSvg();
    if (!svg) return;

    clearStopTimer();
    hoverRunningRef.current = true;

    const release = () => {
      hoverRunningRef.current = false;
      stopTimerRef.current = null;
      scrubFrameRef.current = null;
    };

    /*
     * The tracks only exist while the running class is applied, so recreate them
     * and pin them to the settled end SYNCHRONOUSLY - within one task, before
     * any paint - which is what prevents a flash of frame 0 on hover entry.
     */
    svg.classList.add("share-motion-active");
    void svg.getBoundingClientRect();
    for (const animation of svg.getAnimations({ subtree: true })) {
      animation.pause();
      animation.playbackRate = 1;
      animation.currentTime = CYCLE_DURATION_MS;
    }

    /** Write one authored time to every track. */
    const pinAll = (authoredTime: number) => {
      const current = getSvg();
      if (!current) return false;
      for (const animation of current.getAnimations({ subtree: true })) {
        animation.currentTime = authoredTime;
      }
      return true;
    };

    const scrub = (
      fromProgress: number,
      toProgress: number,
      durationMs: number,
      ease: (x: number) => number,
      onDone: () => void,
    ) => {
      let settled = false;
      const finish = () => {
        if (settled) return;
        settled = true;
        if (scrubFrameRef.current !== null) {
          cancelAnimationFrame(scrubFrameRef.current);
          scrubFrameRef.current = null;
        }
        if (stopTimerRef.current !== null) {
          window.clearTimeout(stopTimerRef.current);
          stopTimerRef.current = null;
        }
        // Land on the exact endpoint, not wherever the last frame fell.
        if (!pinAll(toProgress * CYCLE_DURATION_MS)) {
          release();
          return;
        }
        onDone();
      };

      const startedAt = performance.now();
      const step = (now: number) => {
        const x = Math.min(1, (now - startedAt) / durationMs);
        const progress = fromProgress + (toProgress - fromProgress) * ease(x);
        if (!pinAll(progress * CYCLE_DURATION_MS)) {
          release();
          return;
        }
        if (x >= 1) {
          finish();
          return;
        }
        scrubFrameRef.current = requestAnimationFrame(step);
      };

      scrubFrameRef.current = requestAnimationFrame(step);
      /*
       * requestAnimationFrame is suspended while the tab is hidden, so without
       * this a transaction interrupted by a tab switch would stall mid-pose and
       * latch the guard. Timers still fire, so this completes it the same way.
       */
      stopTimerRef.current = window.setTimeout(finish, durationMs + 250);
    };

    // Reverse, eased -> hold on exact frame 0 -> forward on the approved clock.
    scrub(1, 0, HOVER_REVERSE_MS, easeHoverReverse, () => {
      stopTimerRef.current = window.setTimeout(() => {
        if (!getSvg()) {
          release();
          return;
        }
        scrub(0, 1, CYCLE_DURATION_MS, linearProgress, release);
      }, HOVER_HOLD_MS);
    });
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container || window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      return clearStopTimer;
    }

    const startViewportCycle = () => {
      const svg = container.querySelector<SVGSVGElement>("svg");
      if (!svg) return;

      isHoverReplayReadyRef.current = false;
      clearStopTimer();
      svg.classList.remove("share-motion-active");
      void svg.getBoundingClientRect();
      svg.classList.add("share-motion-active");
      stopTimerRef.current = window.setTimeout(() => {
        svg.classList.remove("share-motion-active");
        isHoverReplayReadyRef.current = true;
        stopTimerRef.current = null;
      }, CYCLE_DURATION_MS + 24);
    };

    let observer: IntersectionObserver | null = null;
    if ("IntersectionObserver" in window) {
      observer = new IntersectionObserver(([entry]) => {
        if (!entry?.isIntersecting) return;
        observer?.disconnect();
        startViewportCycle();
      }, { threshold: 0.35 });
      observer.observe(container);
    } else {
      startViewportCycle();
    }

    return () => {
      observer?.disconnect();
      clearStopTimer();
      isHoverReplayReadyRef.current = false;
      hoverRunningRef.current = false;
      container.querySelector<SVGSVGElement>("svg")?.classList.remove("share-motion-active");
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className="on-demand-visual share-visual"
      style={{ position: "relative" }}
    >
      <div
        role="img"
        aria-label="Beam landing page directory connected to share-link and deployment flows"
        dangerouslySetInnerHTML={{ __html: animatedSvgMarkup }}
      />
      {/*
        No pointer-leave handler: a hover transaction always runs to completion
        and settles on the finished composition, so leaving mid-way must not
        interrupt it.
      */}
      <div
        aria-hidden="true"
        onPointerEnter={handlePointerEnter}
        style={{ position: "absolute", inset: 0 }}
      />
    </div>
  );
}
